package com.leaguepings;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/**
 * Guards against the party protocol's reserved "type" discriminator: a party
 * message with a serialized field named "type" throws JsonParseException on
 * every send, silently breaking pings for the whole party.
 */
public class LeaguePingSerializationTest
{
	@Test
	public void messageMustNotShadowThePartyTypeDiscriminator()
	{
		for (Class<?> c = LeaguePing.class; c != null && c != Object.class; c = c.getSuperclass())
		{
			for (Field field : c.getDeclaredFields())
			{
				if (Modifier.isStatic(field.getModifiers()) || Modifier.isTransient(field.getModifiers()))
				{
					continue;
				}
				assertNotEquals("the party protocol reserves the field name \"type\" for its message discriminator",
					"type", field.getName());
			}
		}
	}

	@Test
	public void leaguePingRoundTripsThroughGson()
	{
		Gson gson = new Gson();
		LeaguePing ping = new LeaguePing(PingType.PRAY_MAGIC, new WorldPoint(3222, 3218, 0));

		LeaguePing back = gson.fromJson(gson.toJson(ping), LeaguePing.class);
		assertEquals(PingType.PRAY_MAGIC, back.getPingType());
		assertEquals(ping.getPoint(), back.getPoint());
	}
}

package com.leaguepings;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LeaguePingsPluginTest
{
