package com.leaguepings;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Config choice for what a quick hotkey+click (released inside the wheel's
 * dead zone, without dragging onto a segment) should send.
 */
@Getter
@RequiredArgsConstructor
public enum QuickPing
{
	DANGER(PingType.DANGER),
	PRAY_MELEE(PingType.PRAY_MELEE),
	PRAY_MAGIC(PingType.PRAY_MAGIC),
	PRAY_RANGED(PingType.PRAY_RANGED),
	NONE(null);

	private final PingType pingType;

	@Override
	public String toString()
	{
		return pingType != null ? pingType.getLabel() : "Off (wheel only)";
	}
}

package com.leaguepings;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The semantic ping types. Enum order is the wheel order, starting at the
 * top segment and going clockwise: Danger up, melee right, magic down,
 * ranged left. Danger is warning-yellow; the prayers use combat-triangle
 * colors (melee red, ranged green, magic blue).
 */
@Getter
@RequiredArgsConstructor
public enum PingType
{
	DANGER("Danger", "Danger!", new Color(0xFD, 0xD8, 0x35)),
	PRAY_MELEE("Pray melee", "Pray melee!", new Color(0xE5, 0x39, 0x35)),
	PRAY_MAGIC("Pray magic", "Pray magic!", new Color(0x1E, 0x88, 0xE5)),
	PRAY_RANGED("Pray ranged", "Pray ranged!", new Color(0x43, 0xA0, 0x47));

	private final String label;
	private final String chatText;
	private final Color color;
}

package com.leaguepings;

import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.Point;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.FocusChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.party.messages.TilePing;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
	name = "Better Pings",
	description = "League of Legends style ping wheel for parties - hold Alt and click a tile to call "
		+ "Danger, Pray melee, Pray magic or Pray ranged",
	tags = {"party", "ping", "pings", "wheel", "pvm", "raids", "prayer", "communication", "lol"}
)
public class LeaguePingsPlugin extends Plugin
{
	static final int WHEEL_RADIUS = 88;
	static final int WHEEL_DEAD_ZONE = 30;

	// guards against a single gesture ever double-firing; not a spam limiter
	private static final long SEND_COOLDOWN_MS = 150;
	private static final int MAX_ACTIVE_PINGS = 32;
	private static final String UNKNOWN_MEMBER_NAME = "<unknown>";

	@Inject
	private Client client;

	@Inject
	private PartyService party;

	@Inject
	private WSClient wsClient;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private LeaguePingsConfig config;

	@Inject
	private PingSounds pingSounds;

	@Inject
	private PingWheelOverlay wheelOverlay;

	@Inject
	private PingSceneOverlay sceneOverlay;

	@Inject
	private PingMinimapOverlay minimapOverlay;

	@Getter
	private final List<ActivePing> activePings = Collections.synchronizedList(new ArrayList<>());

	/**
	 * The open ping wheel, or null when closed. Written on the AWT thread,
	 * read on the client thread by the overlay.
	 */
	@Getter
	private volatile WheelSession wheelSession;

	private volatile boolean hotkeyDown;
	private boolean consumeNextClick;
	private long lastSendAt;
	private final Map<String, Long> lastAlertAt = new HashMap<>();

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.pingHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			hotkeyDown = true;

			if (config.hotkeyOnlyWheel() && wheelSession == null && client.getGameState() == GameState.LOGGED_IN)
			{
				Tile tile = client.getSelectedSceneTile();
				net.runelite.api.Point mouse = client.getMouseCanvasPosition();
				if (tile != null && mouse != null && mouse.getX() != -1)
				{
					wheelSession = new WheelSession(new Point(mouse.getX(), mouse.getY()), tile.getWorldLocation(), true);
				}
			}
		}

		@Override
		public void hotkeyReleased()
		{
			hotkeyDown = false;

			WheelSession session = wheelSession;
			if (session != null && session.keyOnly)
			{
				wheelSession = null;

				PingType selected = hoveredType(session.center, session.getDrag());
				if (selected == null)
				{
					selected = config.quickPing().getPingType();
				}
				if (selected != null)
				{
					sendPing(selected, session.target);
				}
			}
		}

		@Override
		public void focusLost()
		{
			// alt-tab and the like: close the wheel without pinging, before
			// super's focusLost invokes hotkeyReleased
			WheelSession session = wheelSession;
			if (session != null && session.keyOnly)
			{
				wheelSession = null;
			}
			super.focusLost();
		}
	};

	private final MouseAdapter mouseAdapter = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (e.isConsumed())
			{
				return e;
			}

			consumeNextClick = false;

			WheelSession session = wheelSession;
			if (session != null)
			{
				if (session.keyOnly)
				{
					// keyboard-opened wheel: clicks pass through untouched so
					// pinging never blocks movement
					return e;
				}
				// a second button while the wheel is open cancels it
				if (!SwingUtilities.isLeftMouseButton(e))
				{
					wheelSession = null;
				}
				consumeNextClick = true;
				e.consume();
				return e;
			}

			if (hotkeyDown && !config.hotkeyOnlyWheel()
				&& SwingUtilities.isLeftMouseButton(e) && client.getGameState() == GameState.LOGGED_IN)
			{
				Tile tile = client.getSelectedSceneTile();
				if (tile != null)
				{
					wheelSession = new WheelSession(e.getPoint(), tile.getWorldLocation(), false);
					consumeNextClick = true;
					e.consume();
				}
			}

			return e;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent e)
		{
			WheelSession session = wheelSession;
			if (session != null)
			{
				session.setDrag(e.getPoint());
				if (!session.keyOnly)
				{
					e.consume();
				}
			}
			return e;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent e)
		{
			WheelSession session = wheelSession;
			if (session != null)
			{
				session.setDrag(e.getPoint());
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			WheelSession session = wheelSession;
			if (session != null && !session.keyOnly && SwingUtilities.isLeftMouseButton(e))
			{
				wheelSession = null;

				PingType selected = hoveredType(session.center, session.getDrag());
				if (selected == null)
				{
					selected = config.quickPing().getPingType();
				}
				if (selected != null)
				{
					sendPing(selected, session.target);
				}
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			// swallow the click event paired with a press/release we consumed
			if (consumeNextClick)
			{
				consumeNextClick = false;
				e.consume();
			}
			return e;
		}
	};

	@Provides
	LeaguePingsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LeaguePingsConfig.class);
	}

	@Override
	protected void startUp()
	{
		wsClient.registerMessage(LeaguePing.class);
		overlayManager.add(sceneOverlay);
		overlayManager.add(minimapOverlay);
		overlayManager.add(wheelOverlay);
		keyManager.registerKeyListener(hotkeyListener);
		mouseManager.registerMouseListener(mouseAdapter);
	}

	@Override
	protected void shutDown()
	{
		wsClient.unregisterMessage(LeaguePing.class);
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(wheelOverlay);
		keyManager.unregisterKeyListener(hotkeyListener);
		mouseManager.unregisterMouseListener(mouseAdapter);
		wheelSession = null;
		hotkeyDown = false;
		activePings.clear();
		synchronized (lastAlertAt)
		{
			lastAlertAt.clear();
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		if (!event.isFocused())
		{
			hotkeyDown = false;
			wheelSession = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			wheelSession = null;
			activePings.clear();
		}
	}

	@Subscribe
	public void onLeaguePing(LeaguePing ping)
	{
		if (ping.getPingType() == null || ping.getPoint() == null)
		{
			// message from a newer plugin version with an unknown ping type
			return;
		}

		PartyMember local = party.getLocalMember();
		if (local != null && ping.getMemberId() == local.getMemberId())
		{
			// our own ping echoed back; it was already shown on send
			return;
		}

		PartyMember member = party.getMemberById(ping.getMemberId());
		String name = member != null && !Strings.isNullOrEmpty(member.getDisplayName())
			&& !UNKNOWN_MEMBER_NAME.equals(member.getDisplayName())
			? member.getDisplayName()
			: "Party member";

		addPing(ping.getPingType(), ping.getPoint(), name, false);
	}

	private void sendPing(PingType type, WorldPoint point)
	{
		long now = System.currentTimeMillis();
		if (now - lastSendAt < SEND_COOLDOWN_MS)
		{
			return;
		}
		lastSendAt = now;

		// show it locally right away; the party echo of this message is skipped
		addPing(type, point, localName(), true);

		if (party.isInParty())
		{
			party.send(new LeaguePing(type, point));
			if (config.vanillaFallback())
			{
				party.send(new TilePing(point));
			}
		}
	}

	private String localName()
	{
		PartyMember local = party.getLocalMember();
		if (local != null && !Strings.isNullOrEmpty(local.getDisplayName())
			&& !UNKNOWN_MEMBER_NAME.equals(local.getDisplayName()))
		{
			return local.getDisplayName();
		}

		Player player = client.getLocalPlayer();
		return player != null && player.getName() != null ? player.getName() : "You";
	}

	private void addPing(PingType type, WorldPoint point, String memberName, boolean self)
	{
		long now = System.currentTimeMillis();
		long expiresAt = now + config.pingDuration() * 1000L;

		boolean refreshed = false;
		synchronized (activePings)
		{
			for (ActivePing existing : activePings)
			{
				if (existing.getType() == type && existing.getPoint().equals(point)
					&& existing.getMemberName().equals(memberName))
				{
					// same ping again: re-pulse it instead of stacking another copy
					existing.refresh(now, expiresAt);
					refreshed = true;
					break;
				}
			}

			if (!refreshed)
			{
				while (activePings.size() >= MAX_ACTIVE_PINGS)
				{
					activePings.remove(0);
				}
				activePings.add(new ActivePing(type, point, memberName, self, now, expiresAt));
			}
		}

		alert(type, memberName);
	}

	private void alert(PingType type, String memberName)
	{
		int cooldownMs = config.alertCooldown();
		if (cooldownMs > 0)
		{
			long now = System.currentTimeMillis();
			synchronized (lastAlertAt)
			{
				Long last = lastAlertAt.get(memberName);
				if (last != null && now - last < cooldownMs)
				{
					return;
				}
				lastAlertAt.put(memberName, now);
			}
		}

		if (config.chatLines())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage(new ChatMessageBuilder()
					.append(type.getColor(), "[Ping] ")
					.append(memberName)
					.append(": ")
					.append(type.getColor(), type.getChatText())
					.build())
				.build());
		}

		if (config.playSounds())
		{
			pingSounds.play(type, config.soundVolume());
		}
	}

	/**
	 * Maps a drag position to a wheel segment; null inside the dead zone.
	 * Segment 0 is centered on top, continuing clockwise in enum order; the
	 * wheel divides evenly among however many ping types exist.
	 */
	static PingType hoveredType(Point center, Point drag)
	{
		int dx = drag.x - center.x;
		int dy = drag.y - center.y;
		if (dx * dx + dy * dy < WHEEL_DEAD_ZONE * WHEEL_DEAD_ZONE)
		{
			return null;
		}

		PingType[] types = PingType.values();
		double segment = 360.0 / types.length;
		double angle = Math.toDegrees(Math.atan2(dy, dx)); // 0 = east, clockwise positive
		int index = (int) Math.floor((((angle + 90 + segment / 2) % 360) + 360) % 360 / segment);
		return types[index];
	}

	static class WheelSession
	{
		final Point center;
		final WorldPoint target;
		final boolean keyOnly; // opened by the hotkey alone (vs hotkey+click)
		private volatile Point drag;

		WheelSession(Point center, WorldPoint target, boolean keyOnly)
		{
			this.center = center;
			this.target = target;
			this.keyOnly = keyOnly;
			this.drag = center;
		}

		Point getDrag()
		{
			return drag;
		}

		void setDrag(Point drag)
		{
			this.drag = drag;
		}
	}
}

package com.leaguepings;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The radial ping menu, drawn around the point where the player pressed
 * hotkey+click. Segment hit-testing lives in {@link LeaguePingsPlugin} so the
 * visuals and the selection logic can never disagree.
 */
class PingWheelOverlay extends Overlay
{
	private static final Color BACKGROUND = new Color(16, 18, 24, 190);
	private static final Color BORDER = new Color(255, 255, 255, 70);
	private static final int ICON_SIZE = 26;

	private final Client client;
	private final LeaguePingsPlugin plugin;
	private final LeaguePingsConfig config;
	private final PingIcons pingIcons;

	@Inject
	PingWheelOverlay(Client client, LeaguePingsPlugin plugin, LeaguePingsConfig config, PingIcons pingIcons)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.pingIcons = pingIcons;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		LeaguePingsPlugin.WheelSession session = plugin.getWheelSession();
		if (session == null)
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		// outline the tile that will be pinged
		LocalPoint lp = LocalPoint.fromWorld(client, session.target);
		if (lp != null)
		{
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly != null)
			{
				g.setColor(new Color(255, 255, 255, 150));
				g.setStroke(new BasicStroke(2));
				g.draw(poly);
			}
		}

		int cx = session.center.x;
		int cy = session.center.y;
		PingType hovered = LeaguePingsPlugin.hoveredType(session.center, session.getDrag());

		double outer = LeaguePingsPlugin.WHEEL_RADIUS;
		double inner = LeaguePingsPlugin.WHEEL_DEAD_ZONE + 4;
		Area innerCut = new Area(new Ellipse2D.Double(cx - inner, cy - inner, inner * 2, inner * 2));

		PingType[] types = PingType.values();
		double segmentDeg = 360.0 / types.length;
		for (int i = 0; i < types.length; i++)
		{
			PingType type = types[i];
			double centerDeg = -90 + segmentDeg * i; // screen angle of the segment center, clockwise from top
			double arcStart = -centerDeg - segmentDeg / 2; // Java2D arcs are counter-clockwise

			Area segment = new Area(new Arc2D.Double(
				cx - outer, cy - outer, outer * 2, outer * 2, arcStart + 1.5, segmentDeg - 3, Arc2D.PIE));
			segment.subtract(innerCut);

			boolean isHovered = type == hovered;
			g.setColor(isHovered ? translucent(type.getColor(), 215) : BACKGROUND);
			g.fill(segment);
			g.setColor(isHovered ? Color.WHITE : BORDER);
			g.setStroke(new BasicStroke(isHovered ? 2f : 1f));
			g.draw(segment);

			double rad = Math.toRadians(centerDeg);
			double iconRadius = (inner + outer) / 2 + 2;
			int ix = (int) Math.round(cx + Math.cos(rad) * iconRadius);
			int iy = (int) Math.round(cy + Math.sin(rad) * iconRadius);
			g.drawImage(pingIcons.get(type, ICON_SIZE), ix - ICON_SIZE / 2, iy - ICON_SIZE / 2, null);
		}

		// center hub previews the quick-click ping
		double hub = LeaguePingsPlugin.WHEEL_DEAD_ZONE - 4;
		g.setColor(BACKGROUND);
		g.fill(new Ellipse2D.Double(cx - hub, cy - hub, hub * 2, hub * 2));
		g.setColor(hovered == null ? Color.WHITE : BORDER);
		g.setStroke(new BasicStroke(hovered == null ? 2f : 1f));
		g.draw(new Ellipse2D.Double(cx - hub, cy - hub, hub * 2, hub * 2));

		PingType quick = config.quickPing().getPingType();
		if (quick != null)
		{
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.SrcOver.derive(hovered == null ? 1f : 0.45f));
			BufferedImage quickIcon = pingIcons.get(quick, 22);
			g.drawImage(quickIcon, cx - 11, cy - 11, null);
			g.setComposite(old);
		}

		String label = hovered != null ? hovered.getLabel() : (quick != null ? quick.getLabel() : "");
		if (!label.isEmpty())
		{
			g.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics fm = g.getFontMetrics();
			int tx = cx - fm.stringWidth(label) / 2;
			int ty = (int) (cy + outer + 22);
			g.setColor(Color.BLACK);
			g.drawString(label, tx + 1, ty + 1);
			g.setColor(hovered != null ? hovered.getColor() : Color.LIGHT_GRAY);
			g.drawString(label, tx, ty);
		}

		return null;
	}

	private static Color translucent(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.leaguepings;

import java.io.ByteArrayInputStream;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Short synthesized chimes, one per ping type, in the spirit of League's ping
 * sounds. Rendered to an in-memory WAV on first use (so the repo ships no
 * audio assets) and played through the client's AudioPlayer.
 */
@Slf4j
@Singleton
class PingSounds
{
	private static final int SAMPLE_RATE = 44100;

	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;
	private final Map<PingType, byte[]> wavCache = new ConcurrentHashMap<>();

	@Inject
	PingSounds(AudioPlayer audioPlayer, ScheduledExecutorService executor)
	{
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	void play(PingType type, int volumePercent)
	{
		if (volumePercent <= 0)
		{
			return;
		}
		executor.execute(() -> doPlay(type, volumePercent));
	}

	private void doPlay(PingType type, int volumePercent)
	{
		try
		{
			byte[] wav = wavCache.computeIfAbsent(type, PingSounds::renderWav);
			// 100% -> 0 dB; lower volumes attenuate on a log scale
			float gainDb = (float) (20.0 * Math.log10(Math.max(0.02, volumePercent / 100.0)));
			audioPlayer.play(new ByteArrayInputStream(wav), gainDb);
		}
		catch (Exception ex)
		{
			log.debug("Unable to play ping sound", ex);
		}
	}

	/**
	 * A note slides from startHz to endHz over durationMs.
	 */
	private static double[] note(double startHz, double endHz, int durationMs, double volume)
	{
		return new double[]{startHz, endHz, durationMs, volume};
	}

	private static double[][] notesFor(PingType type)
	{
		// pitch register is the mnemonic: melee low, ranged mid, magic high
		switch (type)
		{
			case PRAY_MELEE: // low, sturdy double thump
				return new double[][]{note(330, 330, 100, 1.0), note(247, 247, 190, 1.0)};
			case PRAY_RANGED: // mid rising slide + confirm
				return new double[][]{note(523, 784, 140, 0.9), note(880, 880, 130, 0.9)};
			case PRAY_MAGIC: // high sparkle
				return new double[][]{note(1319, 1319, 60, 0.8), note(1976, 1976, 150, 0.85)};
			case DANGER: // falling alarm interval
			default:
				return new double[][]{note(988, 988, 120, 1.0), note(699, 699, 180, 1.0)};
		}
	}

	private static byte[] renderWav(PingType type)
	{
		return wrapWav(renderPcm(type));
	}

	private static byte[] renderPcm(PingType type)
	{
		double[][] notes = notesFor(type);
		int gapMs = 25;
		int tailMs = 40;

		int totalSamples = 0;
		for (double[] n : notes)
		{
			totalSamples += (int) (SAMPLE_RATE * (n[2] + gapMs) / 1000.0);
		}
		totalSamples += (int) (SAMPLE_RATE * tailMs / 1000.0);

		byte[] out = new byte[totalSamples * 2];
		int cursor = 0;

		for (double[] n : notes)
		{
			double startHz = n[0];
			double endHz = n[1];
			int samples = (int) (SAMPLE_RATE * n[2] / 1000.0);
			double vol = n[3];
			double phase = 0;

			for (int i = 0; i < samples; i++)
			{
				double progress = (double) i / samples;
				double hz = startHz + (endHz - startHz) * progress;
				phase += 2 * Math.PI * hz / SAMPLE_RATE;

				// a few harmonics so it doesn't sound like a bare sine
				double wave = Math.sin(phase) + 0.35 * Math.sin(2 * phase) + 0.12 * Math.sin(3 * phase);

				double attack = Math.min(1.0, i / (SAMPLE_RATE * 0.004));
				double decay = Math.exp(-3.2 * progress);
				double sample = wave * attack * decay * vol * 0.5;

				short s = (short) (Math.max(-1.0, Math.min(1.0, sample)) * Short.MAX_VALUE);
				int idx = (cursor + i) * 2;
				out[idx] = (byte) (s & 0xFF);
				out[idx + 1] = (byte) ((s >> 8) & 0xFF);
			}

			cursor += samples + (int) (SAMPLE_RATE * gapMs / 1000.0);
		}

		return out;
	}

	/**
	 * Wraps raw 16-bit mono PCM in a canonical 44-byte RIFF/WAVE header so
	 * AudioPlayer can identify the format.
	 */
	private static byte[] wrapWav(byte[] pcm)
	{
		byte[] wav = new byte[44 + pcm.length];
		writeAscii(wav, 0, "RIFF");
		writeIntLE(wav, 4, 36 + pcm.length);
		writeAscii(wav, 8, "WAVE");
		writeAscii(wav, 12, "fmt ");
		writeIntLE(wav, 16, 16); // fmt chunk size
		writeShortLE(wav, 20, 1); // PCM
		writeShortLE(wav, 22, 1); // mono
		writeIntLE(wav, 24, SAMPLE_RATE);
		writeIntLE(wav, 28, SAMPLE_RATE * 2); // byte rate
		writeShortLE(wav, 32, 2); // block align
		writeShortLE(wav, 34, 16); // bits per sample
		writeAscii(wav, 36, "data");
		writeIntLE(wav, 40, pcm.length);
		System.arraycopy(pcm, 0, wav, 44, pcm.length);
		return wav;
	}

	private static void writeAscii(byte[] buf, int offset, String text)
	{
		for (int i = 0; i < text.length(); i++)
		{
			buf[offset + i] = (byte) text.charAt(i);
		}
	}

	private static void writeIntLE(byte[] buf, int offset, int value)
	{
		buf[offset] = (byte) (value & 0xFF);
		buf[offset + 1] = (byte) ((value >> 8) & 0xFF);
		buf[offset + 2] = (byte) ((value >> 16) & 0xFF);
		buf[offset + 3] = (byte) ((value >> 24) & 0xFF);
	}

	private static void writeShortLE(byte[] buf, int offset, int value)
	{
		buf[offset] = (byte) (value & 0xFF);
		buf[offset + 1] = (byte) ((value >> 8) & 0xFF);
	}
}

package com.leaguepings;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * A ping currently being displayed.
 */
@Getter
class ActivePing
{
	private final PingType type;
	private final WorldPoint point;
	private final String memberName;
	private final boolean self;
	private long createdAt;
	private long expiresAt;

	ActivePing(PingType type, WorldPoint point, String memberName, boolean self, long createdAt, long expiresAt)
	{
		this.type = type;
		this.point = point;
		this.memberName = memberName;
		this.self = self;
		this.createdAt = createdAt;
		this.expiresAt = expiresAt;
	}

	void refresh(long now, long expiresAt)
	{
		this.createdAt = now; // restart the burst animation
		this.expiresAt = expiresAt;
	}

	boolean isExpired(long now)
	{
		return now >= expiresAt;
	}
}

package com.leaguepings;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws active pings in the 3D scene: a colored tile, an expanding burst
 * ring, and a bobbing type icon with the pinger's name. Also prunes expired
 * pings for all overlays.
 */
class PingSceneOverlay extends Overlay
{
	private static final int ICON_SIZE = 24;
	private static final int ICON_HEIGHT_OFFSET = 150; // local units above the ground
	private static final long BURST_MS = 500;
	private static final long FADE_MS = 500;

	private final Client client;
	private final LeaguePingsPlugin plugin;
	private final PingIcons pingIcons;

	@Inject
	PingSceneOverlay(Client client, LeaguePingsPlugin plugin, PingIcons pingIcons)
	{
		this.client = client;
		this.plugin = plugin;
		this.pingIcons = pingIcons;
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<ActivePing> pings = plugin.getActivePings();
		long now = System.currentTimeMillis();

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		synchronized (pings)
		{
			Iterator<ActivePing> it = pings.iterator();
			while (it.hasNext())
			{
				ActivePing ping = it.next();
				if (ping.isExpired(now))
				{
					it.remove();
					continue;
				}
				renderPing(g, ping, now);
			}
		}

		return null;
	}

	private void renderPing(Graphics2D g, ActivePing ping, long now)
	{
		if (ping.getPoint().getPlane() != client.getPlane())
		{
			return;
		}

		LocalPoint lp = LocalPoint.fromWorld(client, ping.getPoint());
		if (lp == null)
		{
			return;
		}

		long age = now - ping.getCreatedAt();
		float fade = Math.min(1f, (ping.getExpiresAt() - now) / (float) FADE_MS);
		Color color = ping.getType().getColor();

		Composite oldComposite = g.getComposite();
		g.setComposite(AlphaComposite.SrcOver.derive(fade));

		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly != null)
		{
			g.setColor(translucent(color, 50));
			g.fill(poly);
			g.setColor(translucent(color, 210));
			g.setStroke(new BasicStroke(2));
			g.draw(poly);

			if (age < BURST_MS)
			{
				double f = age / (double) BURST_MS;
				Rectangle b = poly.getBounds();
				int w = (int) (b.width * (0.4 + f));
				int h = (int) (b.height * (0.4 + f));
				g.setColor(translucent(color, (int) (190 * (1 - f))));
				g.setStroke(new BasicStroke(3));
				g.draw(new Ellipse2D.Double(b.getCenterX() - w / 2.0, b.getCenterY() - h / 2.0, w, h));
			}
		}

		BufferedImage icon = pingIcons.get(ping.getType(), ICON_SIZE);
		Point iconLoc = Perspective.getCanvasImageLocation(client, lp, icon, ICON_HEIGHT_OFFSET);
		if (iconLoc != null)
		{
			int bob = (int) Math.round(Math.sin(age / 220.0) * 3);
			int ix = iconLoc.getX();
			int iy = iconLoc.getY() + bob;
			g.drawImage(icon, ix, iy, null);

			g.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g.getFontMetrics();
			String name = ping.getMemberName();
			int tx = ix + ICON_SIZE / 2 - fm.stringWidth(name) / 2;
			int ty = iy + ICON_SIZE + 12;
			g.setColor(Color.BLACK);
			g.drawString(name, tx + 1, ty + 1);
			g.setColor(Color.WHITE);
			g.drawString(name, tx, ty);
		}

		g.setComposite(oldComposite);
	}

	private static Color translucent(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

