import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Minimap blips for active pings. Pings beyond minimap range are clamped
 * toward the player so they sit at the minimap edge, League style.
 */
class PingMinimapOverlay extends Overlay
{
	private static final long PULSE_MS = 900;
	private static final long FADE_MS = 500;

	private final Client client;
	private final LeaguePingsPlugin plugin;
	private final LeaguePingsConfig config;

	@Inject
	PingMinimapOverlay(Client client, LeaguePingsPlugin plugin, LeaguePingsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.minimapBlips())
		{
			return null;
		}

		List<ActivePing> snapshot;
		List<ActivePing> pings = plugin.getActivePings();
		synchronized (pings)
		{
			snapshot = new ArrayList<>(pings);
		}

		if (snapshot.isEmpty())
		{
			return null;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		long now = System.currentTimeMillis();

		for (ActivePing ping : snapshot)
		{
			if (ping.getPoint().getPlane() != client.getPlane())
			{
				continue;
			}

			Point mp = minimapPoint(ping.getPoint());
			if (mp == null)
			{
				continue;
			}

			long age = now - ping.getCreatedAt();
			float fade = Math.min(1f, (ping.getExpiresAt() - now) / (float) FADE_MS);
			Color color = ping.getType().getColor();

			Composite oldComposite = g.getComposite();
			g.setComposite(AlphaComposite.SrcOver.derive(fade));

			if (age < PULSE_MS)
			{
				double f = age / (double) PULSE_MS;
				double r = 4 + f * 9;
				g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) (200 * (1 - f))));
				g.setStroke(new BasicStroke(2));
				g.draw(new Ellipse2D.Double(mp.getX() - r, mp.getY() - r, r * 2, r * 2));
			}

			g.setColor(Color.BLACK);
			g.fill(new Ellipse2D.Double(mp.getX() - 4.5, mp.getY() - 4.5, 9, 9));
			g.setColor(color);
			g.fill(new Ellipse2D.Double(mp.getX() - 3.5, mp.getY() - 3.5, 7, 7));

			g.setComposite(oldComposite);
		}

		return null;
	}

	private Point minimapPoint(WorldPoint wp)
	{
		LocalPoint lp = LocalPoint.fromWorld(client, wp);
		if (lp != null)
		{
			Point p = Perspective.localToMinimap(client, lp);
			if (p != null)
			{
				return p;
			}
		}

		// out of minimap range: clamp toward the player so the blip sits at the edge
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint me = player.getWorldLocation();
		int dx = wp.getX() - me.getX();
		int dy = wp.getY() - me.getY();
		double len = Math.hypot(dx, dy);
		if (len == 0)
		{
			return null;
		}

		for (int radius = 18; radius >= 4; radius -= 3)
		{
			if (radius >= len)
			{
				continue;
			}

			WorldPoint clamped = new WorldPoint(
				me.getX() + (int) Math.round(dx / len * radius),
				me.getY() + (int) Math.round(dy / len * radius),
				me.getPlane());

			LocalPoint clp = LocalPoint.fromWorld(client, clamped);
			if (clp == null)
			{
				continue;
			}

			Point p = Perspective.localToMinimap(client, clp);
			if (p != null)
			{
				return p;
			}
		}

		return null;
	}
}

