package com.leaguepings;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;

/**
 * Icons for each ping type: a colored disc carrying the real prayer-book
 * sprite (Protect from Melee/Missiles/Magic) pulled from the game's sprite
 * cache, so nothing is bundled with the plugin. Danger uses a drawn "!", and
 * drawn glyphs stand in until the sprite cache is available.
 */
@Singleton
class PingIcons
{
	private final SpriteManager spriteManager;
	private final Map<String, BufferedImage> cache = new ConcurrentHashMap<>();
	private final Map<String, BufferedImage> fallbackCache = new ConcurrentHashMap<>();

	@Inject
	PingIcons(SpriteManager spriteManager)
	{
		this.spriteManager = spriteManager;
	}

	/**
	 * Must be called on the client thread (overlays render there), since the
	 * sprite cache is only accessible from it.
	 */
	BufferedImage get(PingType type, int size)
	{
		String key = type.name() + '/' + size;
		BufferedImage cached = cache.get(key);
		if (cached != null)
		{
			return cached;
		}

		Integer spriteId = spriteIdFor(type);
		BufferedImage sprite = spriteId != null ? spriteManager.getSprite(spriteId, 0) : null;
		if (spriteId == null || sprite != null)
		{
			BufferedImage img = draw(type, size, sprite);
			cache.put(key, img);
			return img;
		}

		// sprite cache not loaded yet; use a drawn glyph until it is
		return fallbackCache.computeIfAbsent(key, k -> draw(type, size, null));
	}

	@Nullable
	private static Integer spriteIdFor(PingType type)
	{
		switch (type)
		{
			case PRAY_MELEE:
				return SpriteID.Prayeron.PROTECT_FROM_MELEE;
			case PRAY_RANGED:
				return SpriteID.Prayeron.PROTECT_FROM_MISSILES;
			case PRAY_MAGIC:
				return SpriteID.Prayeron.PROTECT_FROM_MAGIC;
			default:
				return null; // danger keeps the drawn glyph
		}
	}

	private static BufferedImage draw(PingType type, int size, @Nullable BufferedImage sprite)
	{
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		float s = size;
		Color c = type.getColor();

		// disc with a darker rim for contrast against any background
		g.setColor(darken(c, 0.45f));
		g.fill(new Ellipse2D.Float(0, 0, s, s));
		g.setColor(c);
		float inset = s * 0.08f;
		g.fill(new Ellipse2D.Float(inset, inset, s - 2 * inset, s - 2 * inset));

		if (sprite != null)
		{
			double target = s * 0.72;
			double scale = Math.min(target / sprite.getWidth(), target / sprite.getHeight());
			int w = (int) Math.round(sprite.getWidth() * scale);
			int h = (int) Math.round(sprite.getHeight() * scale);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(sprite, (size - w) / 2, (size - h) / 2, w, h, null);
			g.dispose();
			return img;
		}

		// dark glyph on bright discs (e.g. danger yellow), white otherwise
		double luminance = (0.299 * c.getRed() + 0.587 * c.getGreen() + 0.114 * c.getBlue()) / 255.0;
		g.setColor(luminance > 0.7 ? new Color(43, 43, 43) : Color.WHITE);
		g.setStroke(new BasicStroke(Math.max(1.5f, s * 0.09f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		switch (type)
		{
			case DANGER:
				drawGlyph(g, "!", s);
				break;
			case PRAY_MELEE:
				drawSword(g, s);
				break;
			case PRAY_MAGIC:
				drawSpark(g, s);
				break;
			case PRAY_RANGED:
				drawArrow(g, s);
				break;
		}

		g.dispose();
		return img;
	}

	private static void drawGlyph(Graphics2D g, String glyph, float s)
	{
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.round(s * 0.68f)));
		FontMetrics fm = g.getFontMetrics();
		int x = Math.round((s - fm.stringWidth(glyph)) / 2f);
		int y = Math.round(s / 2f + (fm.getAscent() - fm.getDescent()) / 2f);
		g.drawString(glyph, x, y);
	}

	private static void drawSword(Graphics2D g, float s)
	{
		// blade up-right, crossguard, short handle
		g.draw(new Line2D.Float(s * 0.38f, s * 0.62f, s * 0.72f, s * 0.28f));
		g.draw(new Line2D.Float(s * 0.30f, s * 0.54f, s * 0.46f, s * 0.70f));
		g.draw(new Line2D.Float(s * 0.38f, s * 0.62f, s * 0.28f, s * 0.72f));
	}

	private static void drawSpark(Graphics2D g, float s)
	{
		// four-pointed magic sparkle
		Path2D star = new Path2D.Float();
		star.moveTo(s * 0.50f, s * 0.18f);
		star.lineTo(s * 0.58f, s * 0.42f);
		star.lineTo(s * 0.82f, s * 0.50f);
		star.lineTo(s * 0.58f, s * 0.58f);
		star.lineTo(s * 0.50f, s * 0.82f);
		star.lineTo(s * 0.42f, s * 0.58f);
		star.lineTo(s * 0.18f, s * 0.50f);
		star.lineTo(s * 0.42f, s * 0.42f);
		star.closePath();
		g.fill(star);
	}

	private static void drawArrow(Graphics2D g, float s)
	{
		// arrow pointing up-right
		g.draw(new Line2D.Float(s * 0.30f, s * 0.70f, s * 0.62f, s * 0.38f));
		Path2D head = new Path2D.Float();
		head.moveTo(s * 0.74f, s * 0.26f);
		head.lineTo(s * 0.46f, s * 0.32f);
		head.lineTo(s * 0.68f, s * 0.54f);
		head.closePath();
		g.fill(head);
	}

	private static Color darken(Color c, float factor)
	{
		return new Color(
			Math.round(c.getRed() * factor),
			Math.round(c.getGreen() * factor),
			Math.round(c.getBlue() * factor));
	}
}
